import{bQ as e,aL as a,u as r,G as o}from"./chunks/framework.C1gZXFVa.js";const n="/assets/040101.4CZwPNTh.png",_=JSON.parse('{"title":"委托初始化链路","description":"委托服务起来之后如何就绪：能接单、能收消息，交易对等规则在首次请求时再装。","frontmatter":{"title":"委托初始化链路","description":"委托服务起来之后如何就绪：能接单、能收消息，交易对等规则在首次请求时再装。","head":[["meta",{"name":"keywords","content":"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX"}],["link",{"rel":"canonical","href":"https://tgex.net/pages/070504"}],["meta",{"property":"og:url","content":"https://tgex.net/pages/070504"}],["meta",{"property":"og:title","content":"委托初始化链路 · TGEX"}],["meta",{"property":"og:description","content":"委托服务起来之后如何就绪：能接单、能收消息，交易对等规则在首次请求时再装。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://tgex.net/og.jpg"}],["meta",{"name":"twitter:title","content":"委托初始化链路 · TGEX"}],["meta",{"name":"twitter:description","content":"委托服务起来之后如何就绪：能接单、能收消息，交易对等规则在首次请求时再装。"}],["meta",{"name":"twitter:image","content":"https://tgex.net/og.jpg"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"TechArticle\\",\\"headline\\":\\"委托初始化链路\\",\\"description\\":\\"委托服务起来之后如何就绪：能接单、能收消息，交易对等规则在首次请求时再装。\\",\\"keywords\\":\\"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX\\",\\"url\\":\\"https://tgex.net/pages/070504\\",\\"mainEntityOfPage\\":\\"https://tgex.net/pages/070504\\",\\"inLanguage\\":\\"zh-CN\\",\\"isPartOf\\":{\\"@type\\":\\"WebSite\\",\\"name\\":\\"TGEX\\",\\"url\\":\\"https://tgex.net/\\"},\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://tgex.net/logo.svg\\"}},\\"image\\":\\"https://tgex.net/og.jpg\\"}"]]},"headers":[],"relativePath":"pages/070504.md","filePath":"07.现货手册/05.核心流程/04.委托初始化链路.md"}'),s={name:"pages/070504.md"};function i(p,t,h,d,l,g){return a(),r("div",null,[...t[0]||(t[0]=[o('<div class="doc-eyebrow">现货手册 · 核心交易流程 / TGEX KNOWLEDGE BASE</div><h1 id="委托初始化链路" tabindex="-1">委托初始化链路 <a class="header-anchor" href="#委托初始化链路" aria-label="Permalink to &quot;委托初始化链路&quot;">​</a></h1><div class="doc-lead">委托服务起来之后，目标很简单：能接住下单 / 撤单 / 查询，能处理相关消息；不会像撮合那样把全站交易对和盘口先灌满。</div><p align="center"><img src="'+n+'" alt="委托初始化链路"></p><p>下文按上图节点展开。和<a href="/pages/070505">撮合初始化链路</a>的差别：撮合要恢复盘口并开放接单；委托只保证「门面在、通道通」，规则与配置多半在第一次真实请求时再取。</p><h2 id="_1-配置与存储通道就绪" tabindex="-1">1. 配置与存储通道就绪 <a class="header-anchor" href="#_1-配置与存储通道就绪" aria-label="Permalink to &quot;1. 配置与存储通道就绪&quot;">​</a></h2><p>配置、数据库、缓存、检索、消息、远程调用等通道先打通。<br> 下游暂时不在线，一般<strong>不挡</strong>本服务起来——真正下单时再依赖对方是否可用。</p><h2 id="_2-对外提供委托能力" tabindex="-1">2. 对外提供委托能力 <a class="header-anchor" href="#_2-对外提供委托能力" aria-label="Permalink to &quot;2. 对外提供委托能力&quot;">​</a></h2><p>此时别人已经能调用：下单、撤单、委托查询、统计、机器人相关能力等。<br> 对业务读者来说，这是「委托服务已上线」的第一层含义：门面在，请求有地方进。</p><h2 id="_3-挂上消息与内部事件消费" tabindex="-1">3. 挂上消息与内部事件消费 <a class="header-anchor" href="#_3-挂上消息与内部事件消费" aria-label="Permalink to &quot;3. 挂上消息与内部事件消费&quot;">​</a></h2><p>开始监听与委托相关的消息和内部事件，例如：限购变更、批量撤单、账务超时补偿、历史委托归档一类。</p><p>启动时只是<strong>挂上监听</strong>，不会把全站历史委托扫一遍。若队列里已有积压，起来后会立刻消化；这和「预热盘口」不是一回事。</p><h2 id="_4-探活确认库可用" tabindex="-1">4. 探活确认库可用 <a class="header-anchor" href="#_4-探活确认库可用" aria-label="Permalink to &quot;4. 探活确认库可用&quot;">​</a></h2><p>定期用很轻的查库确认数据库还通。<br> 探活通过只说明「进程在、库能问」；<strong>不</strong>表示撮合侧每个交易对已经开放接单。</p><h2 id="_5-保持进程在线-不预热全站" tabindex="-1">5. 保持进程在线（不预热全站） <a class="header-anchor" href="#_5-保持进程在线-不预热全站" aria-label="Permalink to &quot;5. 保持进程在线（不预热全站）&quot;">​</a></h2><p>服务保持运行即可。启动阶段<strong>没有</strong>「把所有交易对、所有费率、所有委托灌进内存」这一步。<br> 另有失败消息重试一类运维补偿，属于旁路，不是交易对预热。</p><h2 id="_6-第一次真实请求时再装规则" tabindex="-1">6. 第一次真实请求时再装规则 <a class="header-anchor" href="#_6-第一次真实请求时再装规则" aria-label="Permalink to &quot;6. 第一次真实请求时再装规则&quot;">​</a></h2><p>交易对规则、币种、商户信息、用户费率 / VIP、限购活动等，多在<strong>第一次用到时</strong>再装进本地缓存。</p><p>因此：第一次真实下单，才会去拉交易对能不能买、精度多少、费率多少。<br> 启动日志里看不到撮合那种「交易对初始化成功」是正常的——委托本来就不在启动时做这件事。</p><h2 id="就绪怎么理解" tabindex="-1">就绪怎么理解 <a class="header-anchor" href="#就绪怎么理解" aria-label="Permalink to &quot;就绪怎么理解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问法</th><th>答案</th></tr></thead><tbody><tr><td>能不能调委托接口？</td><td>第二节完成后可以</td></tr><tr><td>消息会不会丢在门口？</td><td>第三节挂上后可以消费</td></tr><tr><td>库通不通？</td><td>看探活</td></tr><tr><td>是不是已经能完整下单？</td><td><strong>还要看</strong>撮合是否开放该交易对、账务 / 币种等下游是否可用——不在委托启动完成时打包保证</td></tr></tbody></table><h2 id="本文边界" tabindex="-1">本文边界 <a class="header-anchor" href="#本文边界" aria-label="Permalink to &quot;本文边界&quot;">​</a></h2><p>用户提交买单 / 撤单首先进委托：校验后再进撮合。启动只保证门面与通道；真实下单见<a href="/pages/070502">下单主流程</a>，撤单见<a href="/pages/070503">撤单主流程</a>。盘口里的历史挂单来自<a href="/pages/070505">撮合初始化链路</a>。</p><p>同组：<a href="/pages/070505">撮合初始化链路</a> · <a href="/pages/070506">账务初始化链路</a> · <a href="/pages/070502">下单主流程</a> · <a href="/pages/070503">撤单主流程</a> · <a href="/pages/070510">委托查询主流程</a></p>',24)])])}const m=e(s,[["render",i]]);export{_ as __pageData,m as default};
